INSERT INTO `hr_letter_templates` (`id`, `title`, `type`, `description`, `content`, `version`, `isActive`, `createdAt`, `updatedAt`) VALUES
('01ac2550-f749-4733-a6fe-8e72c403dfb4', 'Confirmation of Appointment', 'CONFIRMATION', 'Letter confirming staff appointment after probation', 'I am pleased to inform you that following a satisfactory review of your performance during the probationary period, the Management of the Driver and Vehicle Licensing Authority (DVLA) has confirmed your appointment as {{job_title}} in the {{department}} Department, effective {{start_date}}.\n\nYour appointment is now on the permanent establishment of the Authority on {{salary_grade}} of the Approved Salary Structure.\n\nThe Authority congratulates you and hopes you will continue to demonstrate commitment and excellence in your role.', 1, 1, '2026-09-23 12:29:16.309', '2026-09-23 12:29:16.309'),
('1a12795d-0070-42e8-8a3c-36b3eb76222c', 'Leave Approval', 'LEAVE_APPROVAL', 'Official leave approval notification letter', 'I am directed to inform you that your application for leave has been approved by the Management of the Driver and Vehicle Licensing Authority (DVLA).\n\nYou are hereby granted the approved leave commencing {{start_date}}. You are required to resume duty on the date stipulated in your approved leave schedule.\n\nThe Authority expects you to report back promptly on your resumption date. Failure to do so without valid reason may attract disciplinary action.\n\nKindly acknowledge receipt of this letter.', 1, 1, '2026-09-23 12:29:16.372', '2026-09-23 12:29:16.372'),
('3e3c89a8-5c7f-487d-874f-488ce0ced5e5', 'Contract Renewal', 'CONTRACT_RENEWAL', 'Contract renewal offer for existing staff', 'I am pleased to inform you that the Management of the Driver and Vehicle Licensing Authority (DVLA) has reviewed your performance and hereby offers you a renewal of your contract as {{job_title}} in the {{department}} Department, effective {{start_date}}.\n\nThe terms and conditions of your renewed contract remain as previously stipulated unless otherwise amended in writing. Your remuneration continues on {{salary_grade}} of the Authority\'s Approved Salary Structure.\n\nKindly sign and return the duplicate of this letter to indicate your acceptance of the renewal.', 1, 1, '2026-09-23 12:29:16.412', '2026-09-23 12:29:16.412'),
('a508c858-0840-4ca5-98f4-a103a838c209', 'Inter-Departmental Transfer', 'TRANSFER', 'Staff transfer notification between departments', 'I am directed to inform you that the Management of the Driver and Vehicle Licensing Authority (DVLA) has approved your transfer from your current posting to the {{department}} Department, effective {{start_date}}.\n\nYour role at the new posting is {{job_title}}. You are requested to report to the Head of {{department}} for formal handover arrangements prior to assumption of duties.\n\nKindly acknowledge receipt of this letter.', 1, 1, '2026-09-23 12:29:16.343', '2026-09-23 12:29:16.343'),
('cf1717b5-7404-43b0-b281-c8e52d1e0f9d', 'Offer of Appointment', 'APPOINTMENT', 'Standard DVLA appointment letter for new hires', 'I am pleased to convey to you that the Driver and Vehicle Licensing Authority (DVLA) has offered you appointment as {{job_title}} in the {{department}} Department at Head Office, Accra.\n\nYour appointment is subject to a probation period of six (6) months, during which your performance and conduct will be evaluated for confirmation. Your salary and benefits will be attached to {{salary_grade}} of the Authority\'s Approved Salary Structure.\n\nYour assumption of duty takes effect from {{start_date}}.\n\nYou are required to report to the Ag. Director Human Resource on {{start_date}} for formal onboarding and IPPD payroll documentation.\n\nKindly sign and acknowledge receipt of this document.', 1, 1, '2026-09-23 12:29:16.218', '2026-09-23 12:29:16.218'),
('f56d4ae6-d9b4-480b-bef4-dbb42dbc5e21', 'Letter of Promotion', 'PROMOTION', 'Staff promotion notification letter', 'I am pleased to inform you that the Board of the Driver and Vehicle Licensing Authority (DVLA) has approved your promotion to the position of {{job_title}} in the {{department}} Department, effective {{start_date}}.\n\nYour new appointment is on {{salary_grade}} of the Authority\'s Approved Salary Structure.\n\nThe Management of the Authority congratulates you on this achievement and expects that you will justify the confidence reposed in you by your dedication to duty and the high standards of performance the Authority demands.\n\nKindly acknowledge receipt of this letter.', 1, 1, '2026-09-23 12:29:16.264', '2026-09-23 12:29:16.264');
